import{_ as r,a0 as d,w as n,s,ao as a,I as l,x as o,a1 as p,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"初識 Linux 文件權限 | LCTT x X-CMD","titleTemplate":false,"description":"初識 Linux 文件權限 | LCTT (201606) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"初識 Linux 文件權限 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"初識 Linux 文件權限 | LCTT (201606) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201606/20160218 Getting to Know Linux File Permissions","title":"初識 Linux 文件權限","tag":"201606","desc":""},"relativePath":"201606/20160218 Getting to Know Linux File Permissions.md","filePath":"[post].md"}'),c={name:"201606/20160218 Getting to Know Linux File Permissions.md"};function u(x,e,m,w,h,T){const i=d("Link");return n(),s("div",null,[e[13]||(e[13]=a(`<h1 id="初識-linux-文件權限" tabindex="-1">初識 Linux 文件權限 <a class="header-anchor" href="#初識-linux-文件權限" aria-label="Permalink to “初識 Linux 文件權限”">​</a></h1><p>在 Linux 中最基本的任務之一就是設置文件權限。理解如何實現是你進入 Linux 世界的第一步。如您所料，這一基本操作在類 UNIX 操作系統中大同小異。實際上，Linux 文件權限系統就直接取自於 UNIX 文件權限（甚至使用許多相同的工具）。</p><p><img src="http://www.linux.com/images/stories/66866/files_a.png" alt=""></p><p>但不要以為理解文件權限需要長時間的學習。事實上會很簡單，讓我們一起來看看你需要了解哪些內容以及如何使用它們。</p><p>###基礎概念</p><p>你要明白的第一件事是文件權限可以用來幹什麼。當你設置一個分組的權限時發生了什麼？讓我們將其展開來説，這個概念就真的簡單多了。那到底什麼是權限，什麼是分組呢？</p><p>你可以設置的3種權限：</p><ul><li>讀 — 允許該分組讀文件（用<code>r</code>表示）</li><li>寫 — 允許該分組寫文件（用<code>w</code>表示）</li><li>執行 — 允許該分組執行（運行）文件（用<code>x</code>表示）</li></ul><p>為了更好地解釋這如何應用於一個分組，例如，你允許一個分組可以讀寫一個文件，但不能執行。或者，你可以允許一個分組讀和執行一個文件，但不能寫。甚至你可以允許一個分組有讀、寫、執行全部的權限，也可以刪除全部權限來去除該組的權限。</p><p>現在，什麼是分組呢，有以下4個：</p><ul><li>user — 文件實際的擁有者</li><li>group — 用户所在的用户組</li><li>others — 用户組外的其他用户</li><li>all — 所有用户</li></ul><p>大多數情況，你只會對前3組進行操作，<code>all</code> 這一組只是作為快捷方式（稍後我會解釋）。</p><p>到目前為止很簡單，對吧？接下來我們將深入一層。</p><p>如果你打開一個終端並運行命令 <code>ls -l</code>，你將會看到逐行列出當前工作目錄下所有的文件和文件夾的列表（如圖1）.</p><p>你會留意到最左邊那列是像是 <code>-rw-rw-r--</code> 這樣的。</p><p>實際上這列表應該這樣看：</p><blockquote><p>rw- rw- r--</p></blockquote><p>正如你所見，列表將其分為如下3部分：</p><ul><li>rw-</li><li>rw-</li><li>r--</li></ul><p>權限和組的順序都很重要，順序總是：</p><ul><li>所屬者 所屬組 其他人 — 分組</li><li>讀 寫 執行 — 權限</li></ul><p>在我們上面示例的權限列表中，所屬者擁有讀/寫權限，所屬組擁有讀/寫權限，其他人用户僅擁有讀權限。這些分組中賦予執行權限的話，就用一個 x 表示。</p><h3 id="等效數值" tabindex="-1">等效數值 <a class="header-anchor" href="#等效數值" aria-label="Permalink to “等效數值”">​</a></h3><p>接下來我們讓它更復雜一些,每個權限都可以用一個數字表示。這些數字是:</p><ul><li>讀 — 4</li><li>寫 — 2</li><li>執行— 1</li></ul><p>數值代替不是一個一個的替換，你不能像這樣：</p><blockquote><p>-42-42-4--</p></blockquote><p>你該把每個分組的數值相加，給用户讀和寫權限，你該用 4 + 2 得到 6。給用户組相同的權限，也是使用相同的數值。假如你只想給其他用户讀的權限，那就設置它為4。現在用數值表示為：</p><blockquote><p>664</p></blockquote><p>如果你想給一個文件664權限，你可以使用 <code>chmod</code> 命令，如：</p><pre><code>chmod 664 FILENAME
</code></pre><p>FILENAME 處為文件名。</p><h3 id="更改權限" tabindex="-1">更改權限 <a class="header-anchor" href="#更改權限" aria-label="Permalink to “更改權限”">​</a></h3><p>既然你已經理解了文件權限，那是時候學習如何更改這些權限了。就是使用 <code>chmod</code> 命令來實現。第一步你要知道你能否更改文件權限，你必須是文件的所有者或者有權限編輯文件（或者通過 <code>su</code> 或 <code>sudo</code> 得到權限）。正因為這樣，你不能隨意切換目錄和更改文件權限。</p><p>繼續用我們的例子 (<code>-rw-rw-r--</code>)。假設這個文件（命名為 script.sh）實際是個shell腳本，需要被執行，但是你只想讓自己有權限執行這個腳本。這個時候，你可能會想：“我需要是文件的權限如 <code>-rwx-rw-r--</code>”。為了設置 <code>x</code> 權限位，你可以這樣使用 <code>chmod</code> 命令：</p><pre><code>chmod u+x script.sh
</code></pre><p>這時候，列表中顯示的應該是 -rwx-rw-r-- 。</p><p>如果你想同時讓用户及其所屬組同時擁有執行權限，命令應該這樣：</p><pre><code>chmod ug+x script.sh
</code></pre><p>明白這是怎麼工作的了嗎？下面我們讓它更有趣些。不管什麼原因，你不小心給了所有分組對文件的執行權限（列表中是這樣的 <code>-rwx-rwx-r-x</code>）。</p><p>如果你想去除其他用户的執行權限，只需運行命令：</p><pre><code>chmod o-x script.sh
</code></pre><p>如果你想完全刪除文件的可執行權限，你可以用兩種方法：</p><pre><code>chmod ugo-x script.sh
</code></pre><p>或者</p><pre><code>chmod a-x script.sh
</code></pre><p>以上就是所有內容，能使操作更有效率。我希望能避免哪些可能會導致一些問題的操作（例如你不小心對 script.sh 使用 <code>a-rwx</code> 這樣的 <code>chmod</code> 命令）。</p><h3 id="目錄權限" tabindex="-1">目錄權限 <a class="header-anchor" href="#目錄權限" aria-label="Permalink to “目錄權限”">​</a></h3><p>你也可以對一個目錄執行 <code>chmod</code> 命令。當你作為用户創建一個新的目錄，通常新建目錄具有這樣的權限：</p><blockquote><p>drwxrwxr-x</p></blockquote><p>注：開頭的 <code>d</code> 表示這是一個目錄。</p><p>正如你所見，用户及其所在組都對文件夾具有操作權限，但這並不意味着在這文件夾中出創建的文件也具有與其相同的權限（創建的文件使用默認系統的權限 <code>-rw-rw-r--</code>）。但如果你想在新文件夾中創建文件，並且移除用户組的寫權限，你不用切換到該目錄下並對所有文件使用 <code>chmod</code> 命令。你可以用加上參數 R（意味着遞歸）的 <code>chmod</code> 命令，同時更改該文件夾及其目錄下所有的文件的權限。</p><p>現在，假設有一文件夾 TEST，裏面有一些腳本，所有這些（包括 TEST 文件夾）擁有權限 <code>-rwxrwxr-x</code>。如果你想移除用户組的寫權限，你可以運行命令：</p><pre><code>chmod -R g-w TEST
</code></pre><p>運行命令 <code>ls -l</code>，你講看到列出的 TEST 文件夾的權限信息是 <code>drwxr-xr-x</code>。用户組被去除了寫權限（其目錄下的所有文件也如此）。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>現在，你應該對基本的 Linux 文件權限有了深入的理解。對於更高級的東西學起來會很輕鬆，像 setgid、setuid 和 ACL 這些。沒有良好的基礎，你很快就會混淆不清概念的。</p><p>Linux 文件權限從早期到現在沒有太大變化，而且很可能以後也不會變化。</p><hr>`,59)),l("p",null,[e[1]||(e[1]=o("via: ",-1)),p(i,{href:"http://www.linux.com/learn/tutorials/885268-getting-to-know-linux-file-permissions"},{default:t(()=>[...e[0]||(e[0]=[o("http://www.linux.com/learn/tutorials/885268-getting-to-know-linux-file-permissions",-1)])]),_:1})]),l("p",null,[e[5]||(e[5]=o("作者：",-1)),p(i,{href:"http://www.linux.com/community/forums/person/93"},{default:t(()=>[...e[2]||(e[2]=[o("Jack Wallen",-1)])]),_:1}),e[6]||(e[6]=o(" 譯者：",-1)),p(i,{href:"https://github.com/ynmlml"},{default:t(()=>[...e[3]||(e[3]=[o("ynmlml",-1)])]),_:1}),e[7]||(e[7]=o(" 校對：",-1)),p(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),l("p",null,[e[10]||(e[10]=o("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原創翻譯，",-1)),p(i,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[o("Linux中國",-1)])]),_:1}),e[12]||(e[12]=o(" 榮譽推出",-1))])])}const b=r(c,[["render",u]]);export{g as __pageData,b as default};
